base=json.loads((R/'startup.json').read_text())['head_after_successful_SSH_fetch'];prefix=subprocess.check_output(['git','show',base+':research/automation/registry.jsonl'],cwd=ROOT);raw=(ROOT/'research/automation/registry.jsonl').read_bytes();assert raw.startswith(prefix) and hashlib.sha256(prefix).hexdigest()==ctx['main_registry_sha256_before_reserve'];events=[json.loads(x) for x in raw[len(prefix):].splitlines()];allrows=batch+json.loads((R/'forward_batch.json').read_text())+json.loads((R/'candidate_batch.json').read_text());assert len(events)==92 and len(allrows)==len({x['fingerprint'] for x in allrows})==46 and {x['fingerprint'] for x in events}=={x['fingerprint'] for x in allrows}
